    mov     d1, a2                          # a2 = &entry.width
    mov     (4, a2), a1                     # a1 = entry.pixels: the source
    mov     d0, (0xc, sp)                   # (0xc,sp) = &entry.height
    movhu   (a0), d0
    clr     d3                              # d3 = row
    exth    d0
    cmp     d3, d0
    ble     DrawBitmap_Impl_Dirty           # height <= 0
    mov     2, d0
    add     a3, d0
    mov     d0, (0x10, sp)                  # (0x10,sp) = &point.y

