    movhu   (0x34, sp), d0
    exth    d0
    mov     d0, (0x24, sp)                  # (0x24,sp) = stride
    movhu   (0x36, sp), d0
    exth    d0
    mov     d0, (0x28, sp)                  # (0x28,sp) = width

Draw2BpFile_Impl_RowLoop:
    mov     a3, a0
